/// The items below are pub(crate).
/// One tab in the tab bar.
#[derive(Clone, Debug, PartialEq, Eq)]
struct TabRow {
    pub view: kate_core::ViewId,
    pub title: String,
    pub modified: bool,
    pub active: bool,
}

/// The items below are pub(crate).
/// One row per view in `Workspace::views_in_order`.
fn tab_rows(ws: &kate_core::Workspace) -> Vec<TabRow>
